"use client";

import { memo } from "react";
import { WordmarkShader, type WordmarkSourceProps } from "./wordmark-shader.shared";
import wordmarkLedShader from "./wordmark-led.wgsl";

const surface = { dpr: [1, 2] as const };
const uniforms = (time: number, x: number, y: number, hovering: boolean) => ({
  params: { time: [time, x, y, Number(hovering)] },
});

export const WordmarkLed = memo(function WordmarkLed(props: WordmarkSourceProps = {}) {
  return (
    <WordmarkShader
      {...props}
      shader={wordmarkLedShader}
      label="wordmark-led"
      uniforms={uniforms}
      surface={surface}
    />
  );
});

struct Theme { mode: vec4f };
@group(1) @binding(0) var<uniform> theme: Theme;

struct Params {
  time: vec4f,  // x: seconds, y: pointer x (0..1), z: pointer y (0..1), w: hover strength
};

@group(0) @binding(0) var<uniform> params: Params;

// The wordmark surface is 1337x336 (about 4:1), so 64x16 cells are already square. No size uniform needed.

const COLS = 64.0;
const ROWS = 16.0;
const IDLE = 0.16;  // brightness of LEDs outside the beam and the hover glow

fn led_hash(cell: vec2f) -> f32 {
  return fract(sin(dot(cell, vec2f(127.1, 311.7))) * 43758.5453);
}

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let grid = uv * vec2f(COLS, ROWS);
  let cell = floor(grid);
  let local = fract(grid) - vec2f(0.5);
  let radius = length(local);

  let aa = max(fwidth(radius) * 0.75, 0.035);
  let led = 1.0 - smoothstep(0.275 - aa, 0.275 + aa, radius);

  // The beam travels 10 cells past each edge so it has fully faded before it wraps.
  let span = COLS + 20.0;
  let scan_x = fract(params.time.x * 6.0 / span) * span - 10.0;
  let scan_distance = abs(cell.x - scan_x);
  let scan = exp(-scan_distance * scan_distance / 18.0);

  let pointer_cell = vec2f(params.time.y * COLS, params.time.z * ROWS);
  let pointer_distance = distance(cell + vec2f(0.5), pointer_cell);
  let hover_glow = exp(-pointer_distance * pointer_distance / 20.0) * params.time.w;

  let variation = 0.82 + led_hash(cell) * 0.18;
  let energy = led * (IDLE + scan * 0.9 + hover_glow * 1.0) * variation;

  if (theme.mode.x > 0.5) {
    let coverage = led * (0.5 + scan * 0.65 + hover_glow * 0.8) * variation;
    return vec4f(vec3f(1.0 - min(coverage, 1.0)), 1.0);
  }
  return vec4f(vec3f(min(energy, 1.0)), 1.0);
}

import {
  effect,
  frame,
  frameLoop,
  init,
  sampler,
  surface,
  target,
  type Frame,
  type SurfaceOptions,
} from "vgpu";

type ShaderSource = Parameters<typeof effect>[1];
type Bindings = Parameters<ReturnType<typeof effect>["set"]>[0];

export interface PostProcessOptions {
  label: string;
  source: ShaderSource;
  uniforms?: (time: number, size: readonly [number, number]) => Bindings;
}

interface ShaderRendererOptions {
  label: string;
  uniforms: (time: number, size: readonly [number, number]) => Bindings;
  animated?: boolean;
  fps?: number;
  surface?: SurfaceOptions;
  postProcess?: PostProcessOptions;
  themeAware?: boolean;
  themeMask?: boolean;
}

/** Owns one canvas effect. Components supply bindings and retain their own input/UI logic. */
export function createShaderRenderer(
  canvas: HTMLCanvasElement,
  source: ShaderSource,
  {
    label,
    uniforms,
    animated = true,
    fps = 60,
    surface: surfaceOptions = { dpr: 1 },
    postProcess,
    themeAware = true,
    themeMask = false,
  }: ShaderRendererOptions,
) {
  let disposed = false;
  let gpu: Awaited<ReturnType<typeof init>> | undefined;
  let output: ReturnType<typeof surface> | undefined;
  let scene: ReturnType<typeof target> | undefined;
  let themeObserver: MutationObserver | undefined;
  let light = themeAware && !document.documentElement.classList.contains("dark");
  const theme = () => ({ mode: [Number(light), Number(themeMask), 0, 0] });
  let sceneSampler: ReturnType<typeof sampler> | undefined;
  let shader: ReturnType<typeof effect> | undefined;
  let postShader: ReturnType<typeof effect> | undefined;
  let loop: ReturnType<typeof frameLoop> | undefined;
  let observer: ResizeObserver | undefined;
  let unsubscribeResize: (() => void) | undefined;
  let pendingFrame = 0;
  let draw: ((currentFrame: Frame) => void) | undefined;
  canvas.style.opacity = "0";

  const dispose = () => {
    if (disposed) return;
    disposed = true;
    loop?.stop();
    observer?.disconnect();
    themeObserver?.disconnect();
    cancelAnimationFrame(pendingFrame);
    unsubscribeResize?.();
    shader?.dispose();
    postShader?.dispose();
    output?.dispose();
    gpu?.dispose();
  };
  const render = () => {
    if (disposed || !draw || animated) return;
    cancelAnimationFrame(pendingFrame);
    pendingFrame = requestAnimationFrame(() => {
      if (!disposed && gpu && draw) frame(gpu, draw);
    });
  };
  const start = async () => {
    const initialized = await init();
    if (disposed) {
      initialized.dispose();
      return;
    }
    gpu = initialized;
    output = surface(gpu, canvas, surfaceOptions);
    scene = postProcess ? target(gpu, { size: output.size }) : undefined;
    sceneSampler = postProcess
      ? sampler(gpu, { minFilter: "linear", magFilter: "linear" })
      : undefined;
    light = themeAware && !document.documentElement.classList.contains("dark");
    shader = effect(gpu, source, {
      label,
      set: { ...uniforms(0, (scene ?? output).size), theme: theme() },
    });
    postShader = postProcess
      ? effect(gpu, postProcess.source, {
          label: postProcess.label,
          set: {
            theme: theme(),
            scene: scene,
            sceneSampler,
            ...postProcess.uniforms?.(0, output.size),
          },
        })
      : undefined;
    await shader.compile(scene ?? output);
    await postShader?.compile(output);
    if (disposed) return;
    const startedAt = performance.now();
    if (output && scene && sceneSampler) {
      unsubscribeResize = output.onResize(({ width, height }) => {
        scene?.resize([width, height]);
        postShader?.set({
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(0, [width, height]),
        });
      });
    }
    draw = (currentFrame) => {
      if (!output || !shader || disposed) return;
      const time = animated ? (performance.now() - startedAt) / 1000 : 0;
      const renderTarget = scene ?? output;
      shader.set({ ...uniforms(time, renderTarget.size), theme: theme() });
      if (postShader && scene && sceneSampler) {
        postShader.set({
          theme: theme(),
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(time, output.size),
        });
        currentFrame.pass(scene, shader);
        currentFrame.pass(output, postShader);
      } else {
        currentFrame.pass(scene ?? output, shader);
      }
      canvas.style.opacity = "1";
    };
    if (themeAware) {
      themeObserver = new MutationObserver(() => {
        light = themeAware && !document.documentElement.classList.contains("dark");
        render();
      });
      themeObserver.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["class"],
      });
    }
    if (animated) loop = frameLoop(gpu, draw, { fps });
    else {
      observer = new ResizeObserver(render);
      observer.observe(canvas);
      render();
    }
  };
  void start().catch((error: unknown) => {
    if (!disposed) {
      canvas.style.opacity = "0";
      console.warn(`${label} could not start; retaining its fallback:`, error);
      dispose();
    }
  });
  return { dispose, render };
}

// Dedicated pigments for light-mode shader materials. No output filtering.
export fn lightPaper() -> vec3f { return vec3f(0.9568627, 0.9803922, 0.9647059); }
export fn lightSurface() -> vec3f { return vec3f(0.8470588, 0.9333333, 0.8862745); }
export fn lightInk() -> vec3f { return vec3f(0.0666667, 0.2352941, 0.1960784); }
export fn lightEmerald() -> vec3f { return vec3f(0.0000000, 0.4862745, 0.3450980); }
export fn lightCyan() -> vec3f { return vec3f(0.0000000, 0.5450980, 0.7215686); }
export fn lightBlue() -> vec3f { return vec3f(0.1568627, 0.3686275, 0.9098039); }
export fn lightViolet() -> vec3f { return vec3f(0.5098039, 0.2666667, 0.8470588); }
export fn lightRose() -> vec3f { return vec3f(0.8392157, 0.2352941, 0.5137255); }
export fn lightGold() -> vec3f { return vec3f(0.8431373, 0.5764706, 0.1137255); }

"use client";

import { memo, useEffect, useRef } from "react";
import { useReducedMotion } from "motion/react";
import { createShaderRenderer } from "./shader-renderer.shared";

type RendererOptions = Parameters<typeof createShaderRenderer>[2];
export interface WordmarkSourceProps {
  src?: string;
  alt?: string;
}

interface WordmarkShaderProps extends WordmarkSourceProps {
  shader: Parameters<typeof createShaderRenderer>[1];
  label: string;
  uniforms: (
    time: number,
    x: number,
    y: number,
    hovering: boolean,
  ) => ReturnType<RendererOptions["uniforms"]>;
  surface?: RendererOptions["surface"];
  baseBrightness?: number;
}

export const WordmarkShader = memo(function WordmarkShader({
  shader,
  label,
  uniforms,
  surface,
  baseBrightness = 0,
  src = "/wordmark.svg",
  alt = "Hangry UI",
}: WordmarkShaderProps) {
  const image = `url(${JSON.stringify(src)})`;
  const lightImage = src === "/wordmark.svg" ? 'url("/wordmark-light.svg")' : image;
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const markRef = useRef<HTMLDivElement>(null);
  const reducedMotion = useReducedMotion();

  useEffect(() => {
    const canvas = canvasRef.current;
    const mark = markRef.current;
    if (!canvas || !mark) return;
    let x = 0.5;
    let y = 0.5;
    let hovering = false;
    const renderer = createShaderRenderer(canvas, shader, {
      label,
      themeMask: true,
      surface,
      animated: !reducedMotion,
      uniforms: (time) => uniforms(time, x, y, hovering),
    });
    const move = (event: PointerEvent) => {
      const bounds = mark.getBoundingClientRect();
      if (!bounds.width || !bounds.height) return;
      x = Math.max(0, Math.min(1, (event.clientX - bounds.left) / bounds.width));
      y = Math.max(0, Math.min(1, (event.clientY - bounds.top) / bounds.height));
      hovering = true;
      renderer.render();
    };
    const leave = () => {
      hovering = false;
      renderer.render();
    };
    mark.addEventListener("pointermove", move);
    mark.addEventListener("pointerleave", leave);
    mark.addEventListener("pointercancel", leave);
    return () => {
      mark.removeEventListener("pointermove", move);
      mark.removeEventListener("pointerleave", leave);
      mark.removeEventListener("pointercancel", leave);
      renderer.dispose();
    };
  }, [shader, label, uniforms, surface, reducedMotion]);

  return (
    <div className="relative flex h-full w-full items-center justify-center overflow-hidden bg-white dark:bg-background isolate">
      <div
        ref={markRef}
        role={alt ? "img" : undefined}
        aria-label={alt || undefined}
        aria-hidden={alt ? undefined : true}
        className="isolate aspect-[1337/336] w-[88%] bg-(image:--wordmark-light) dark:bg-(image:--wordmark-dark)"
        style={
          {
            "--wordmark-light": lightImage,
            "--wordmark-dark": image,
            backgroundPosition: "center",
            backgroundRepeat: "no-repeat",
            backgroundSize: "contain",
            maskImage: image,
            maskPosition: "center",
            maskRepeat: "no-repeat",
            maskSize: "contain",
            WebkitMaskImage: image,
            WebkitMaskPosition: "center",
            WebkitMaskRepeat: "no-repeat",
            WebkitMaskSize: "contain",
          } as import("react").CSSProperties
        }
      >
        <div
          className="h-full w-full mix-blend-screen dark:mix-blend-multiply"
          style={{ opacity: 1 - baseBrightness }}
        >
          <canvas ref={canvasRef} aria-hidden="true" className="block h-full w-full grayscale" />
        </div>
      </div>
    </div>
  );
});
